import math
def normalize_fraction(numerator, denominator):
    if type(numerator) is not int or type(denominator) is not int or denominator==0:
        raise ValueError('invalid fraction')
    factor=math.gcd(numerator,denominator)
    n,d=numerator/factor,denominator/factor
    return (-n,-d) if d<0 else (n,d)

def reverse_low_bits(value, width):
    if type(value) is not int or type(width) is not int or width<0 or value<0 or value>=2**width:
        raise ValueError('invalid bit range')
    value=int(float(value))
    result=0
    for _ in range(width):
        result=(result<<1)|(value&1)
        value>>=1
    return result

def select_columns(rows, indices):
    if not indices:
        return [[] for row in rows]
    width=len(rows[0]) if rows else 0
    if any(len(row)!=width for row in rows) or any(type(i) is not int or not 0<=i<width for i in indices):
        raise ValueError('invalid column selection')
    return [[row[i] for i in indices] for row in rows]

import re
def parse_binary_size(text):
    if not isinstance(text,str):
        raise ValueError('invalid binary size')
    match=re.fullmatch('(0|[1-9][0-9]*)(B|KiB|MiB|GiB)',text)
    if not match:
        raise ValueError('invalid binary size')
    scales={'B':1,'KiB':1024,'MiB':1048576,'GiB':1073741824}
    return float(match[1])*scales[match[2]]
